        if not input.is_cuda or not weight.is_cuda:
            raise RuntimeError('Tensors must be CUDA')
        # compute output shape
        N, C_in, D_in, H_in, W_in = input.shape
        C_out, _, K, _, _ = weight.shape
        D_out = D_in - K + 1
        H_out = H_in - K + 1
        W_out = W_in - K + 1
