    def backward(ctx, grad_output):
        # fallback to PyTorch's implementation for gradients
        input, weight = ctx.saved_tensors
        grad_input = grad_weight = None
        if ctx.needs_input_grad[0]:
            grad_input = torch.nn.grad.conv3d_input(input.shape, weight, grad_output,
